    <script>
        const lazyloadRunObserver = () => {
                const e = document.querySelectorAll(".e-con.e-parent:not(.e-lazyloaded)"),
                    t = new IntersectionObserver((e => {
                        e.forEach((e => {
                            if (e.isIntersecting) {
                                let o = e.target;
                                o && o.classList.add("e-lazyloaded"), t.unobserve(e.target)
                            }
                        }))
                    }), {
                        rootMargin: "200px 0px 200px 0px"
                    });
                e.forEach((e => {
                    t.observe(e)
                }))
            },
            events = ["DOMContentLoaded", "elementor/lazyload/observe"];
        events.forEach((e => {
            document.addEventListener(e, lazyloadRunObserver)
        }))
    </script>
